const lunarDate=(day,month,year,tz=7)=>{const jd=(d,m,y)=>{const a=Math.floor((14-m)/12),yy=y+4800-a,mm=m+12*a-3;let n=d+Math.floor((153*mm+2)/5)+365*yy+Math.floor(yy/4)-Math.floor(yy/100)+Math.floor(yy/400)-32045;return n<2299161?d+Math.floor((153*mm+2)/5)+365*yy+Math.floor(yy/4)-32083:n;},newMoon=k=>{const T=k/1236.85,T2=T*T,T3=T2*T,dr=Math.PI/180;let j=2415020.75933+29.53058868*k+0.0001178*T2-0.000000155*T3+0.00033*Math.sin((166.56+132.87*T-0.009173*T2)*dr),M=359.2242+29.10535608*k-0.0000333*T2-0.00000347*T3,Mp=306.0253+385.81691806*k+0.0107306*T2+0.00001236*T3,F=21.2964+390.67050646*k-0.0016528*T2-0.00000239*T3;let C= (0.1734-0.000393*T)*Math.sin(M*dr)+0.0021*Math.sin(2*M*dr)-0.4068*Math.sin(Mp*dr)-0.0161*Math.sin(2*Mp*dr)-0.0004*Math.sin(3*Mp*dr)+0.0104*Math.sin(2*F*dr)-0.0051*Math.sin((M+Mp)*dr)-0.0074*Math.sin((M-Mp)*dr)-0.0004*Math.sin((2*F+M)*dr)-0.0004*Math.sin((2*F-M)*dr)-0.0006*Math.sin((2*F+Mp)*dr)+0.001*Math.sin((2*F-Mp)*dr)+0.0005*Math.sin((2*Mp+M)*dr),dt=T< -11?0.001+0.000839*T+0.0002261*T2-0.00000845*T3-0.000000081*T*T3:-0.000278+0.000265*T+0.000262*T2;return j+C-dt;},moonDay=k=>Math.floor(newMoon(k)+0.5+tz/24),sunSector=j=>{const T=(j-2451545)/36525,T2=T*T,dr=Math.PI/180,M=357.5291+35999.0503*T-0.0001559*T2-0.00000048*T*T2,L0=280.46645+36000.76983*T+0.0003032*T2;let L=(L0+(1.9146-0.004817*T-0.000014*T2)*Math.sin(M*dr)+(0.019993-0.000101*T)*Math.sin(2*M*dr)+0.00029*Math.sin(3*M*dr))*dr;L-=2*Math.PI*Math.floor(L/(2*Math.PI));return Math.floor(L/Math.PI*6);},month11=y=>{const off=jd(31,12,y)-2415021;let k=Math.floor(off/29.530588853),n=moonDay(k);if(sunSector(n)>=9)n=moonDay(k-1);return n;},leapOffset=a11=>{const k=Math.floor(0.5+(a11-2415021)/29.530588853);let last=0,i=1,arc=sunSector(moonDay(k+i));do{last=arc;i++;arc=sunSector(moonDay(k+i));}while(arc!==last&&i<14);return i-1;};const dn=jd(day,month,year);let k=Math.floor((dn-2415021.076998695)/29.530588853),start=moonDay(k+1);if(start>dn)start=moonDay(k);let a11=month11(year),b11=a11,lunarYear;if(a11>=start){lunarYear=year;a11=month11(year-1);}else{lunarYear=year+1;b11=month11(year+1);}const lunarDay=dn-start+1,diff=Math.floor((start-a11)/29);let lunarMonth=diff+11,leap=0;if(b11-a11>365){const leapMonth=leapOffset(a11);if(diff>=leapMonth){lunarMonth=diff+10;if(diff===leapMonth)leap=1;}}if(lunarMonth>12)lunarMonth-=12;if(lunarMonth>=11&&diff<4)lunarYear--;return{day:lunarDay,month:lunarMonth,year:lunarYear,leap};};
function vietnameseHoliday(date){const[,month,day]=date.split('-').map(Number),fixed={'01-01':'Tết Dương lịch','04-30':'Ngày Giải phóng miền Nam','05-01':'Quốc tế Lao động','09-02':'Quốc khánh','10-20':'Ngày Phụ nữ Việt Nam','11-20':'Ngày Nhà giáo Việt Nam'},key=`${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`;if(fixed[key])return fixed[key];const lunar=lunarDate(day,month,Number(date.slice(0,4)));if(lunar.month===1&&lunar.day<=3)return'Tết Nguyên Đán';if(lunar.month===3&&lunar.day===10)return'Giỗ Tổ Hùng Vương';return'';}
