function showBirthdayGreeting(){const me=state.bootstrap?.me;if(!me||!state.bootstrap?.birthdays?.some(e=>e.id===me.id&&e.dateOfBirth?.slice(5)===state.bootstrap.today.slice(5)))return;const overlay=document.createElement('div');overlay.className='birthday-celebration';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-labelledby','birthday-title');overlay.innerHTML=`<div class="birthday-confetti" aria-hidden="true">${Array.from({length:24},(_,i)=>`<i style="--i:${i};left:${(i*41+7)%100}%;animation-duration:${5+i%5*.7}s"></i>`).join('')}</div><section class="birthday-card"><button class="birthday-close" type="button" aria-label="Đóng">×</button><div class="birthday-glow" aria-hidden="true"></div><div class="birthday-cake" aria-hidden="true">🎂</div><p class="birthday-kicker">HÔM NAY LÀ NGÀY ĐẶC BIỆT</p><h1 id="birthday-title">Chúc mừng sinh nhật!</h1><div class="birthday-name">${E(me.name)}</div><p class="birthday-message">Chúc bạn tuổi mới thật nhiều sức khỏe, niềm vui và luôn rực rỡ trên hành trình của mình cùng Gold Ninh Bình.</p><div class="birthday-wishes" aria-hidden="true"><span>✦</span><span>🎈</span><span>✧</span><span>🎁</span><span>✦</span></div><button class="btn primary birthday-done" type="button">Cảm ơn nhé!</button></section>`;const close=()=>{overlay.classList.add('closing');setTimeout(()=>overlay.remove(),180);};overlay.querySelector('.birthday-close').onclick=close;overlay.querySelector('.birthday-done').onclick=close;overlay.addEventListener('click',event=>{if(event.target===overlay)close();});document.addEventListener('keydown',function onEscape(event){if(event.key==='Escape'&&document.body.contains(overlay)){close();document.removeEventListener('keydown',onEscape);}});document.body.append(overlay);overlay.querySelector('.birthday-done').focus();}
const initials=n=>n.split(' ').filter(Boolean).slice(-2).map(x=>x[0]).join('');
