const badge=(s,text)=>`<span class="badge ${['manager','hr','partner','late','early-checkin'].includes(s)?'yellow':['rejected','early-leave','offsite','late-offsite','early-leave-offsite','early-checkin-offsite'].includes(s)?'red':s==='cancelled'?'gray':s==='swap'?'purple':''}">${E(text||statusLabels[s]||s)}</span>`;
const requestBadge=r=>badge(r.status,['regular','leave','explanation','supplement'].includes(r.type)&&['manager','hr','pending'].includes(r.status)?'Chờ duyệt':undefined);
const hr=()=>['hr','admin'].includes(state.bootstrap?.me.role);
