const panel=(title,content,extra='',sub='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${extra}</div>${content}</section>`;
const empty=message=>`<div class="empty-state">${message}</div>`;
