const range=()=>{const[y,m]=state.month.split('-').map(Number);return{from:state.month+'-01',to:`${state.month}-${new Date(y,m,0).getDate()}`}};
function monthSelector(){const[y,m]=state.month.split('-').map(Number),months=[];for(let offset=-18;offset<=3;offset++){const date=new Date(y,m-1+offset,1),value=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`,label=new Intl.DateTimeFormat('vi-VN',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(`${value}-01T00:00:00Z`));months.push(`<option value="${value}" ${value===state.month?'selected':''}>${E(label.charAt(0).toUpperCase()+label.slice(1))}</option>`);}return`<select id="month" aria-label="Chọn tháng">${months.join('')}</select>`;}
function toast(message){const notice=$('#toast'),dialog=$('#dialog');if(dialog?.open){dialog.insertBefore(notice,dialog.firstChild);notice.classList.add('modal-toast');}else{if(notice.parentElement!==document.body)document.body.append(notice);notice.classList.remove('modal-toast');}notice.textContent=message;notice.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>{notice.style.display='none';if(notice.classList.contains('modal-toast')){notice.classList.remove('modal-toast');document.body.append(notice);}},5000);}
function tokenExpiry(token){try{const encoded=token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'),payload=JSON.parse(atob(encoded.padEnd(Math.ceil(encoded.length/4)*4,'=')));return Number(payload.exp)*1000||0;}catch{return 0;}}
function clearExpiredSession(){const active=!!state.token||!!sessionStorage.getItem('gold.token');clearTimeout(sessionExpiryTimer);sessionExpiryTimer=null;sessionStorage.removeItem('gold.token');sessionStorage.removeItem('gold.refresh');sessionStorage.removeItem('gold.refreshExpiresAt');state.token=null;state.bootstrap=null;state.profile=null;state.attendance=[];state.schedule=[];state.requests=[];sessionRefreshTask=null;if(active){login();toast('Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.');}}
function saveSession(data){state.token=data.accessToken;sessionStorage.setItem('gold.token',state.token);sessionStorage.setItem('gold.refresh',data.refreshToken);if(data.refreshTokenExpiresAt)sessionStorage.setItem('gold.refreshExpiresAt',data.refreshTokenExpiresAt);scheduleSessionExpiry();}
function scheduleSessionExpiry(){clearTimeout(sessionExpiryTimer);const refreshExpiry=Date.parse(sessionStorage.getItem('gold.refreshExpiresAt')||'');const accessExpiry=tokenExpiry(state.token);const expiry=refreshExpiry||(accessExpiry?accessExpiry+14*24*60*60*1000:0);if(!expiry)return;sessionExpiryTimer=setTimeout(clearExpiredSession,Math.max(0,expiry-Date.now()));}
function refreshSession(){if(sessionRefreshTask)return sessionRefreshTask;const refreshToken=sessionStorage.getItem('gold.refresh');if(!refreshToken){clearExpiredSession();return Promise.reject(Error('Phiên đăng nhập đã hết hạn.'));}sessionRefreshTask=api('auth/refresh','POST',{refreshToken,deviceName:'GoldCheckin Web'},false).then(data=>{saveSession(data);return data;}).finally(()=>{sessionRefreshTask=null;});return sessionRefreshTask;}
async function hydrateAvatarImages(){for(const image of document.querySelectorAll('.avatar img[data-private-avatar]')){if(image.dataset.avatarLoading==='true')continue;image.dataset.avatarLoading='true';try{const response=await fetch(image.dataset.privateAvatar,{cache:'no-store',headers:{Authorization:'Bearer '+state.token,'Cache-Control':'no-cache'}});if(!response.ok)throw Error();const blob=await response.blob();if(!blob.type.startsWith('image/'))throw Error();const objectUrl=URL.createObjectURL(blob),previous=image.dataset.objectUrl;if(previous)URL.revokeObjectURL(previous);image.dataset.objectUrl=objectUrl;image.src=objectUrl;}catch{image.closest('.avatar')?.replaceChildren(document.createTextNode(initials(image.dataset.avatarName||image.alt||state.profile?.fullName||state.bootstrap?.me?.name||'?')));if(image.dataset.privateAvatar===state.profile?.avatarUrl)state.profile.avatarUrl=null;}}}
window.addEventListener('error',event=>{
 if(event.message?.includes('noConflict')||event.filename?.startsWith('chrome-extension://')||event.filename?.startsWith('moz-extension://'))return;
 if(event.target instanceof HTMLImageElement){
  const holder=event.target.closest('.avatar');
  if(holder){holder.textContent=initials(event.target.dataset.avatarName||event.target.alt||state.profile?.fullName||state.bootstrap?.me?.name||'?');holder.dataset.avatarError='true';}
  if(state.profile&&event.target.dataset.privateAvatar===state.profile.avatarUrl)state.profile.avatarUrl=null;
  return;
 }
 if(event.message)toast('Đã xảy ra lỗi: '+event.message);
});
window.addEventListener('unhandledrejection',event=>{const message=event.reason?.message||String(event.reason||'Lỗi không xác định.');toast(message);});
async function api(path,method='GET',body,retry=true){
 let response;
 try{response=await fetch('/api/'+path,{method,headers:{...(state.token?{Authorization:'Bearer '+state.token}:{}),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});}
 catch{throw Error('Không kết nối được máy chủ. Vui lòng kiểm tra kết nối và thử lại.');}
 const result=await response.json().catch(()=>({message:'Máy chủ trả phản hồi không hợp lệ.'}));
 if(response.status===405&&path==='gold/face-scan')throw Error('Máy chủ GoldCheckin hiện chưa hỗ trợ quét mặt. Hãy khởi động lại/cập nhật API GoldCheckin để route POST /api/gold/face-scan được nạp.');
 if(response.status===401){
  if(path==='accounts/login')throw Error(result.message||'Tên đăng nhập hoặc mật khẩu không đúng, hoặc tài khoản đã bị khóa.');
  const refreshToken=sessionStorage.getItem('gold.refresh');
  if(retry&&refreshToken&&path!=='auth/refresh'){
   try{await refreshSession();return api(path,method,body,false);}catch{clearExpiredSession();throw Error('Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.');}
  }
  clearExpiredSession();throw Error('Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.');
 }
 if(!response.ok||result.success===false)throw Error(Object.values(result.errors||{}).flat().join('\n')||result.message||'Không thực hiện được yêu cầu.');
 return result.data;
}
function login(){
 $('#sidebar').style.display='none';$('.shell').style.marginLeft='0';$('header').style.display='none';
 $('#main').innerHTML=`<div class="login-layout"><section class="login-brand"><img src="logo.png" alt="Gold Ninh Bình"><div class="eyebrow">CÔNG TY CỔ PHẦN Y TẾ TOÀN CẦU</div><h1>Chăm sóc sức khỏe.<br>Kết nối đội ngũ.</h1><p>Không gian chấm công và quản lý nhân sự<br>dành cho Gold Ninh Bình.</p><div class="login-services"><span>✚ Tiêm chủng quốc tế</span><span>✧ Phục hồi chức năng · Y học cổ truyền</span><span>◇ Da liễu · Thẩm mỹ</span></div></section><section class="login-form panel"><div class="eyebrow">GOLD CHECKIN</div><h1>Chào mừng trở lại</h1><p>Đăng nhập để bắt đầu ngày làm việc của bạn.</p><form id="login-form"><label class="field">Tên đăng nhập<input name="username" autocomplete="username" required placeholder="Nhập tên đăng nhập"></label><label class="field">Mật khẩu<input type="password" name="password" autocomplete="current-password" required placeholder="Nhập mật khẩu"></label><p id="login-error" class="error-message" role="alert"></p><button class="btn primary" type="submit">Đăng nhập &nbsp; →</button></form><small>Hệ thống nhân sự nội bộ · Gold Ninh Bình</small></section></div>`;
 $('#login-form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;$('#login-error').textContent='';try{const data=await api('accounts/login','POST',Object.fromEntries(new FormData(event.target)));saveSession(data);await load();showBirthdayGreeting();}catch(err){$('#login-error').textContent=err.message;}finally{button.disabled=false;}};
}
async function load(){
 try{state.bootstrap=await api('gold/bootstrap');state.profile=await api('accounts/me');await loadMonth();$('#sidebar').style.display='';$('.shell').style.marginLeft='';$('header').style.display='';$('.demo-pill').textContent='Dữ liệu trực tiếp';$('.demo-pill').classList.add('live');
 const me=state.bootstrap.me,avatar=state.profile?.avatarUrl;const avatarMarkup=avatar?`<img data-private-avatar="${E(avatar)}" alt="${E(me.name)}">`:E(initials(me.name));$('.sidebar-bottom').innerHTML=`<span class="avatar">${avatarMarkup}</span><div>${E(me.name)}<small>${E({admin:'Quản trị hệ thống',hr:'Hành chính · Nhân sự',manager:'Trưởng phòng',employee:'Nhân viên'}[me.role])}</small></div><button class="icon-button" data-action="logout" aria-label="Đăng xuất">↪</button>`;const headerAvatar=$('.header-right .avatar');headerAvatar.innerHTML=avatarMarkup;headerAvatar.classList.add('profile-toggle');headerAvatar.setAttribute('role','button');headerAvatar.setAttribute('tabindex','0');let accountMenu=document.querySelector('#account-menu');if(!accountMenu){accountMenu=document.createElement('div');accountMenu.id='account-menu';accountMenu.className='account-menu';$('.header-right').append(accountMenu);}accountMenu.innerHTML=`<b>${E(me.name)}</b><small>${E(state.profile?.email||'')}</small><button data-account="profile">Thông tin cá nhân</button><button data-account="password">Đổi mật khẩu</button><button data-account="logout">Đăng xuất</button>`;const toggleMenu=()=>accountMenu.classList.toggle('open');headerAvatar.onclick=toggleMenu;headerAvatar.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')toggleMenu();};accountMenu.onclick=e=>{const action=e.target.dataset.account;if(!action)return;if(action==='logout')return document.querySelector('.sidebar-bottom [data-action="logout"]').click();accountMenu.classList.remove('open');if(action==='profile')return accountProfileModal();if(action==='password')return changePasswordModal();};document.addEventListener('click',e=>{if(!e.target.closest('.header-right'))accountMenu.classList.remove('open');});if(state.bootstrap.me.role!=='admin'&&!state.bootstrap.faceReady&&(!location.hash||location.hash==='#overview'))location.hash='#checkin';render();hydrateAvatarImages();if(state.page==='requests'&&!manager()){document.querySelector('#search')?.remove();document.querySelector('#department')?.remove();}
 }catch(err){if(state.token){$('#main').innerHTML=`${panel('Chưa thể tải hệ thống',`<div class="panel-body"><p class="error-message">${E(err.message)}</p><p>Kiểm tra cơ sở dữ liệu, migration hoặc hồ sơ nhân viên.</p><div class="form-actions">${buttons('Thử lại','reload')}${buttons('Đăng xuất','logout','')}</div></div>`)}`;bind();}else login();}
}
async function loadMonth(){const{from,to}=range();const q=`?from=${from}&to=${to}`;const values=await Promise.all(['attendance','schedule','requests'].map(k=>api('gold/'+k+q)));[state.attendance,state.schedule,state.requests]=values;}
function nav(){const admin=state.bootstrap.me.role==='admin',hrUser=state.bootstrap.me.role==='hr',managerUser=state.bootstrap.me.role==='manager';const groups=[['QUẢN LÝ',[['overview','▦'],...(admin?[['schedule','▦'],['departments','▥']]:[])]],...(!admin?[['KHÔNG GIAN LÀM VIỆC',[['checkin','◎'],['attendance','▤'],['schedule','▦'],['requests','▧'],['explanations','✎']]]]:[]),...(manager()?[['QUẢN LÝ NHÂN SỰ',[['employees','♧'],...(hr()&&!admin?[['departments','▥']]:[]),['reports','↗']]],['QUẢN LÝ ĐƠN DUYỆT',[['approvals','✓'],...(admin||hrUser||managerUser?[['explanation-approvals','✎']]:[]),...(admin||managerUser?[['supplement-approvals','↻']]:[])]]]:[]),...(hr()?[['THIẾT LẬP HỆ THỐNG',[['shifts','◷'],['locations','⌖'],['policy','⚙'],...(admin?[['logs','≡']]:[])]]]:[])];
 $('#nav').innerHTML=groups.map(([group,items])=>`<label>${group}</label>${items.map(([key,icon])=>`<a href="#${key}" class="${state.page===key?'active':''}"><em>${icon}</em>${labels[key]}${key==='approvals'?`<span class="count">${state.requests.filter(r=>!['explanation','supplement'].includes(r.type)&&canReview(r)).length}</span>`:key==='explanation-approvals'?`<span class="count">${state.requests.filter(r=>r.type==='explanation'&&(canReview(r)||canViewDepartmentRequest(r))).length}</span>`:key==='supplement-approvals'?`<span class="count">${state.requests.filter(r=>r.type==='supplement'&&(canReview(r)||canViewDepartmentRequest(r))).length}</span>`:''}</a>`).join('')}`).join('');
}
function pageTitle(title,description,actions=''){return`<div class="page-title"><div><div class="eyebrow">GOLD NINH BÌNH</div><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
function stats(){const day=state.bootstrap.today;const people=state.bootstrap.employees;const records=state.attendance.filter(r=>r.date===day);const present=new Set(records.filter(r=>r.type==='in').map(r=>r.employeeId)).size;const off=state.schedule.filter(s=>s.date===day&&s.kind!=='work').length;const late=records.filter(r=>r.type==='in'&&['late','late-offsite'].includes(r.status)).length;return[['Nhân viên',people.length,'♧','Trong phạm vi quản lý'],['Đã chấm công vào',present,'✓','Ghi nhận trong hôm nay'],['Nghỉ hôm nay',off,'◷','Theo lịch đã được duyệt'],['Đi muộn',late,'↗','Cần theo dõi và giải trình']].map(([name,num,icon,sub])=>`<div class="stat"><div class="stat-top">${name}<span class="stat-icon">${icon}</span></div><strong>${num}<small>người</small></strong><div class="stat-foot">${sub}</div></div>`).join('');}
function overview(){
 const me=state.bootstrap.me;const pending=state.requests.filter(r=>!['approved','rejected','cancelled'].includes(r.status));
 let chart='';for(let i=6;i>=0;i--){const d=new Date(state.bootstrap.today+'T12:00:00');d.setDate(d.getDate()-i);const day=d.toISOString().slice(0,10);const count=new Set(state.attendance.filter(r=>r.date===day&&r.type==='in').map(r=>r.employeeId)).size;const off=state.schedule.filter(s=>s.date===day&&s.kind!=='work').length;const total=Math.max(1,state.bootstrap.employees.length);chart+=`<div class="bar-group"><div class="bar" style="height:${Math.max(count?3:0,count/total*100)}%" title="${dateLabel(day)}: ${count} đi làm"></div><div class="bar gold" style="height:${Math.max(off?3:0,off/total*100)}%" title="${off} nghỉ"></div><label>${d.getDate()}/${d.getMonth()+1}</label></div>`;}
 const dept=state.bootstrap.departments.map(d=>{const people=state.bootstrap.employees.filter(e=>e.departmentId===d.id);const ids=new Set(people.map(e=>e.id));const present=new Set(state.attendance.filter(a=>a.date===state.bootstrap.today&&a.type==='in'&&ids.has(a.employeeId)).map(a=>a.employeeId)).size;return`<div class="progress-row"><div class="progress-title"><span>${E(d.name)}</span><span>${present}/${people.length}</span></div><div class="progress"><div style="width:${people.length?present/people.length*100:0}%"></div></div></div>`;}).join('');
 return pageTitle('Tổng quan nhân sự','Theo dõi ngày làm việc, kết nối đội ngũ Gold.',`${monthSelector()}${buttons('↓ Xuất báo cáo','export','')}`)+`<section class="hero"><div><div class="eyebrow">MỖI NGÀY LÀM VIỆC, MỘT GIÁ TRỊ MỚI</div><h2>Xin chào, ${E(me.name)} 👋</h2><p>Đồng hành cùng đội ngũ để mang đến dịch vụ chăm sóc sức khỏe tốt nhất.<br>${new Date(state.bootstrap.today+'T12:00:00').toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</p></div><a class="btn gold" href="#schedule">Xem lịch làm việc &nbsp; →</a></section><div class="stats">${stats()}</div><div class="grid">${panel('Nhịp làm việc của đội ngũ',`<div class="panel-body"><div class="chart">${chart}</div><div class="legend"><span><i></i>Đã chấm công</span><span><i class="gold"></i>Nghỉ theo lịch</span></div></div>`,`<span class="badge gray">7 ngày gần nhất</span>`)}${panel('Cần bạn quan tâm',`<div class="panel-body"><div class="alert"><span class="symbol">◷</span><div><b>${pending.length} yêu cầu đang chờ xử lý</b><p>Theo quy trình Trưởng phòng cùng phòng ban hoặc admin</p></div></div><div class="alert green"><span class="symbol">▦</span><div><b>Đăng ký lịch nghỉ</b><p>Đăng ký ngày chưa qua; sửa trước ngày nghỉ khi lịch chưa khóa. Có ${state.bootstrap.policy.regularDays} ngày nghỉ thông thường. Nghỉ Chủ nhật hoặc từ 5 ngày cần giải trình và người bàn giao.</p></div></div>${!state.bootstrap.faceReady?`<div class="alert"><span class="symbol">◎</span><div><b>Chờ tích hợp xác thực khuôn mặt</b><p>Cần dịch vụ nhận diện và liveness để bật chấm công.</p></div></div>`:''}</div>`)} </div><div class="grid">${panel('Hoạt động chấm công',attendanceTable(state.attendance.slice(0,5)),`<a href="#attendance">Xem tất cả →</a>`,'Các lượt vào / ra gần nhất')}${panel('Nhân sự theo phòng ban',`<div class="panel-body">${dept}</div>`,`<a href="#departments">7 phòng ban →</a>`)}</div>`;
}
function attendanceTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>NHÂN VIÊN</th><th>NGÀY / GIỜ</th><th>LOẠI</th><th>TRẠNG THÁI</th><th>LỆCH CA</th><th>GPS / GIẢI TRÌNH</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${person(r.name,r.department)}</td><td>${dateLabel(r.date)}<small>${timeLabel(r.recordedAt)}</small></td><td>${r.type==='in'?'Vào':'Ra'}</td><td>${badge(r.status)}</td><td>${r.deviationMinutes?`${r.deviationMinutes} phút`:'—'}</td><td>${Math.round(r.distanceMeters)} m · ±${Math.round(r.gpsAccuracy)} m${r.reason?`<small>${E(r.reason)}</small>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có bản ghi chấm công trong khoảng thời gian này.');}
function timesheetTable(teamView=canViewTeamAttendance()){const rows=state.schedule.filter(s=>!teamView||(s.name.toLowerCase().includes(state.filter.toLowerCase())&&(!state.department||state.bootstrap.employees.find(e=>e.id===s.employeeId)?.department===state.department))).sort((a,b)=>b.date.localeCompare(a.date)||a.name.localeCompare(b.name));return rows.length?`<div class="table-wrap"><table><thead><tr><th>NHÂN VIÊN</th><th>NGÀY / CA</th><th>GIỜ VÀO</th><th>GIỜ RA</th><th>TRẠNG THÁI</th></tr></thead><tbody>${rows.map(s=>{const employee=state.bootstrap.employees.find(e=>e.id===s.employeeId),beforeStart=employee?.employmentStartDate&&s.date<employee.employmentStartDate,records=state.attendance.filter(a=>a.employeeId===s.employeeId&&a.date===s.date);const entered=records.find(r=>r.type==='in'),exited=records.find(r=>r.type==='out');const unusual=records.find(r=>!['normal','explained','supplemented'].includes(r.status));const key=s.kind!=='work'?s.kind:unusual?.status||(entered&&exited?'normal':s.date>state.bootstrap.today?'cancelled':entered?'manager':s.date===state.bootstrap.today?'manager':'rejected');const text=s.kind!=='work'?statusLabels[s.kind]:unusual?statusLabels[unusual.status]+' '+(unusual.deviationMinutes||'')+(unusual.deviationMinutes?' phút':''):entered&&exited?'Đủ lượt vào / ra':s.date>state.bootstrap.today?'Theo lịch':entered?'Thiếu giờ ra':s.date===state.bootstrap.today?'Chưa chấm công':'Vắng / thiếu chấm công';return`<tr><td>${person(s.name,employee?.code||'')}</td><td>${dateLabel(s.date)}<small>${E(s.shift||'—')}</small></td><td>${timeLabel(entered?.recordedAt)}</td><td>${timeLabel(exited?.recordedAt)}</td><td>${beforeStart?'':badge(key,text)}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Chưa có lịch làm việc trong tháng này.');}
function attendance(){const teamView=canViewTeamAttendance(),filters=teamView?toolbar():`<div class="toolbar">${monthSelector()}</div>`,records=teamView?state.attendance.filter(r=>r.name.toLowerCase().includes(state.filter.toLowerCase())&&(!state.department||r.department===state.department)):state.attendance;return pageTitle(teamView?'Bảng công':'Bảng công cá nhân',teamView?'Giờ vào / ra theo lịch làm việc trong phạm vi quản lý.':'Theo dõi giờ vào / ra của bạn theo tháng.',`${buttons('Bổ sung chấm công','supplement','')}${buttons('↓ Xuất Excel','export')}`)+panel(`Bảng công tháng ${state.month}`,filters+timesheetTable(teamView),hr()?buttons('Khóa bảng công','lock-attendance',''):'')+`<div style="margin-top:22px">${panel('Chi tiết lượt chấm công',attendanceTable(records))}</div>`;}
function toolbar(){return`<div class="toolbar"><input id="search" placeholder="Tìm theo tên nhân viên…" value="${E(state.filter)}" aria-label="Tìm nhân viên"><select id="department" aria-label="Lọc phòng ban"><option value="">Tất cả phòng ban</option>${state.bootstrap.departments.map(d=>`<option ${state.department===d.name?'selected':''}>${E(d.name)}</option>`).join('')}</select>${monthSelector()}</div>`;}
function departments(){return pageTitle('Phòng ban','Quản lý danh sách phòng ban và cấu hình ca làm việc.',buttons('+ Thêm phòng ban','department'))+`<div class="department-grid">${state.bootstrap.departments.map((d,i)=>{const employees=state.bootstrap.employees.filter(e=>e.departmentId===d.id),rows=(state.bootstrap.departmentShifts||[]).filter(x=>x.departmentId===d.id),names=period=>rows.filter(x=>x.period===period).map(x=>state.bootstrap.shifts.find(s=>s.id===x.shiftId)?.name).filter(Boolean);return`<section class="panel dept"><div class="dept-icon">${['✧','✚','♡','⊞','♧','↗','▤'][i%7]}</div><div class="eyebrow">PHÒNG BAN ${String(i+1).padStart(2,'0')}</div><h2>${E(d.name)}</h2>${d.description?`<p class="department-description">${E(d.description)}</p>`:''}<div class="department-shift-summary"><p><b>Ca sáng:</b> ${names('morning').map(E).join(', ')||'Chưa cấu hình'}</p><p><b>Ca chiều:</b> ${names('afternoon').map(E).join(', ')||'Chưa cấu hình'}</p><p><b>Ca tối:</b> ${names('evening').map(E).join(', ')||'Chưa cấu hình'}</p></div><div class="dept-foot"><span>♧ ${employees.length} nhân viên</span><div class="department-actions"><button class="btn" data-action="department-shifts" data-id="${d.id}">Chọn ca</button><button class="btn" data-action="department-edit" data-id="${d.id}">Sửa</button><button class="btn danger" data-action="department-delete" data-id="${d.id}">Xóa</button></div></div></section>`;}).join('')||empty('Chưa có phòng ban nào. Hãy thêm phòng ban đầu tiên.')}</div>`;}
function departmentForm(id){const d=state.bootstrap.departments.find(x=>x.id===id);return formModal(id?'Sửa phòng ban':'Thêm phòng ban',`${field('Tên phòng ban',`<input name="name" maxlength="150" value="${E(d?.name||'')}" placeholder="Ví dụ: Phòng Hành chính nhân sự" required>`,true)}${field('Mô tả',`<textarea name="description" maxlength="500" placeholder="Thông tin mô tả (không bắt buộc)">${E(d?.description||'')}</textarea>`,true)}`,async data=>{await api(id?`gold/departments/${id}`:'gold/departments',id?'PUT':'POST',{name:data.name,description:data.description||''});},'Lưu phòng ban',id?'Đã cập nhật phòng ban.':'Đã thêm phòng ban.');}
function activeLeaveRequests(date){return state.requests.filter(r=>['regular','leave'].includes(r.type)&&!['rejected','cancelled'].includes(r.status)&&!(r.isCancellation&&r.status==='approved')&&(!date||(r.from<=date&&r.to>=date)));}
function leavePeriod(r){const names={morning:'Ca sáng',afternoon:'Ca chiều',full:'Cả ngày'},start=(r.leaveStart||'07:30').slice(0,5),end=(r.leaveEnd||'17:30').slice(0,5);if(r.from===r.to)return `${E(names[r.leaveSession]||'Cả ngày')} · ${E(start)}–${E(end)} · ${r.leaveSession==='full'?'1':'0,5'} ngày`;const first=start>='12:00'?'afternoon':'full',last=end<='12:00'?'morning':'full';return `${E(names[first])} ${E(dateLabel(r.from))} ${E(start)} → ${E(names[last])} ${E(dateLabel(r.to))} ${E(end)}`;}
function leaveSessionRows(){const find=word=>state.bootstrap.shifts.find(s=>s.name.toLowerCase().includes(word)),morning=find('sáng'),afternoon=find('chiều'),full=find('hành chính')||find('cả ngày');return[['morning','Ca sáng',morning?.start||'07:30',morning?.end||'11:30'],['afternoon','Ca chiều',afternoon?.start||'13:30',afternoon?.end||'17:30'],['full','Cả ngày',full?.start||'07:30',full?.end||'17:30']];}
