 openModal('Chi tiết nhân viên',`<div class="employee-detail"><div class="employee-detail-hero">${person(e.name,e.code,avatar)}${badge('role-'+(e.goldRole||'employee'),role)}</div><section><h3>Thông tin nhân sự</h3><div class="employee-detail-grid">${item('Mã nhân viên',E(e.code))}${item('Tên đăng nhập',E(e.username||account?.username))}${item('Phòng ban',E(e.department))}${item('Chức danh',E(e.position))}${item('Ngày sinh',e.dateOfBirth?E(dateLabel(e.dateOfBirth)):'Chưa cập nhật')}${item('Bắt đầu làm',e.employmentStartDate?E(dateLabel(e.employmentStartDate)):'Chưa cập nhật')}${item('Phép năm còn lại',`${E(e.annualLeaveBalance??0)} ngày`)}${item('Trạng thái',e.isActive?'Đang hoạt động':'Đã khóa')}${item('Vai trò nhân sự',E(role))}${item('Đăng ký khuôn mặt',e.faceEnrolled?'Đã đăng ký':'Chưa đăng ký')}${e.faceRegisteredAt?item('Ngày đăng ký khuôn mặt',E(dateLabel(e.faceRegisteredAt.slice(0,10)))):''}${accountInfo}</div></section>${accountError?`<p class="error-message" role="alert">Không tải được đầy đủ thông tin tài khoản: ${E(accountError)}</p>`:''}<div class="employee-detail-actions">${hr()?`<button class="btn" data-action="employee" data-id="${e.id}">Chỉnh sửa hồ sơ</button>`:''}${isAdmin?`<button class="btn" data-action="admin-reset-password" data-id="${e.id}">Cấp lại mật khẩu</button>`:''}${isAdmin&&e.isActive?`<button class="btn primary" data-action="face-enroll" data-id="${e.id}">${e.faceEnrolled?'Đăng ký lại khuôn mặt':'Đăng ký khuôn mặt'}</button>`:''}</div></div>`);
 hydrateAvatarImages();
