 const selectedMonth=state.month,c=await api('gold/regular-leave?month='+encodeURIComponent(selectedMonth)),selected=new Set(),removed=new Map(),registered=new Set(c.registeredDates),blocked=new Set(c.blockedDates);
 if(c.month!==selectedMonth)throw Error('Máy chủ chưa đồng bộ tháng lịch. Hãy khởi động lại ứng dụng và tải lại trang.');const people=(state.bootstrap.colleagues||[]).filter(e=>e.id!==state.bootstrap.me.id);
