 function stopCamera(){faceScanActive=false;document.querySelector('.face-capture-ring')?.classList.remove('face-scanning');if(cameraStream){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null;}}
 function captureCameraFrame(video,quality=.78,maxWidth=640){if(!video||!video.videoWidth)throw Error('Camera chưa có khung hình. Hãy giữ khuôn mặt trong khung và thử lại.');const sourceSize=Math.min(video.videoWidth,video.videoHeight),sx=(video.videoWidth-sourceSize)/2,sy=(video.videoHeight-sourceSize)*.38,outputSize=Math.min(maxWidth,sourceSize),canvas=document.createElement('canvas');canvas.width=outputSize;canvas.height=outputSize;canvas.getContext('2d').drawImage(video,sx,sy,sourceSize,sourceSize,0,0,outputSize,outputSize);return canvas.toDataURL('image/jpeg',quality);}
 async function scanFaceUntilDetected(video,button,status){faceScanActive=true;faceScanAngles=new Set();const ring=document.querySelector('.face-capture-ring');ring?.classList.add('face-scanning');ring?.querySelectorAll('[data-scan-angle]').forEach(segment=>segment.classList.remove('active'));button.disabled=true;button.textContent='Đang quét khuôn mặt…';const started=Date.now(),angleLabels={center:'Nhìn thẳng',left:'Quay sang trái',right:'Quay sang phải'};while(faceScanActive&&cameraStream){if(Date.now()-started>180000){faceScanActive=false;stopCamera();button.dataset.action='face-enroll-self';button.textContent='Quét lại khuôn mặt';button.disabled=false;status.innerHTML='<span class="symbol">◎</span><div><b>Chưa hoàn tất quét</b><p>Kiểm tra CompreFace, rồi nhìn thẳng và quay chậm sang hai bên để ba cung quét chuyển xanh.</p></div>';return;}try{const frame=captureCameraFrame(video,.58,360),result=await api('gold/face-scan','POST',{imageBase64:frame});if(result.faceCount===1&&['center','left','right'].includes(result.angle)){const angle=result.angle;faceScanAngles.add(angle);ring?.querySelector(`[data-scan-angle="${angle}"]`)?.classList.add('active');if(faceScanAngles.size===3){pendingFaceImage=captureCameraFrame(video,.84,640);let preview=$('#self-face-preview');if(!preview){preview=document.createElement('img');preview.id='self-face-preview';preview.className='face-capture-preview';preview.alt='Ảnh khuôn mặt đã quét';status.after(preview);}preview.src=pendingFaceImage;preview.hidden=false;faceScanActive=false;ring?.classList.remove('face-scanning');button.dataset.action='face-register-self';button.textContent='Lưu khuôn mặt';button.disabled=false;status.innerHTML='<span class="symbol">✓</span><div><b>Đã quét đủ ba góc khuôn mặt</b><p>Kiểm tra ảnh rồi bấm Lưu khuôn mặt.</p></div>';return;}const nextAngle=['center','left','right'].find(value=>!faceScanAngles.has(value));status.innerHTML=`<span class="symbol">✓</span><div><b>Đã nhận diện: ${angleLabels[angle]}</b><p>Tiếp tục ${angleLabels[nextAngle].toLocaleLowerCase('vi')} để cung tiếp theo sáng xanh.</p></div>`;}else if(result.faceCount>1){status.innerHTML='<span class="symbol">◎</span><div><b>Đang thấy nhiều khuôn mặt</b><p>Chỉ để một người trong khung hình.</p></div>';}else if(result.faceCount===1){status.innerHTML='<span class="symbol">◎</span><div><b>Chưa xác định được hướng mặt</b><p>Nhìn thẳng hoặc quay chậm hơn để máy nhận đủ điểm khuôn mặt.</p></div>';}else{status.innerHTML='<span class="symbol">◎</span><div><b>Đang tìm khuôn mặt</b><p>Đưa mặt vào giữa khung, nhìn thẳng và đủ sáng.</p></div>';} }catch(error){faceScanActive=false;stopCamera();button.dataset.action='face-enroll-self';button.textContent='Thử quét lại';button.disabled=false;status.innerHTML=`<span class="symbol">!</span><div><b>Không thể quét khuôn mặt</b><p>${E(error.message)}</p></div>`;return;}await new Promise(resolve=>setTimeout(resolve,900));}}
function requestLocation(showToast=false){const status=$('#gps-status');if(!status)return Promise.resolve(null);if(!window.isSecureContext){status.textContent='Vị trí cần HTTPS hoặc localhost. Mở địa chỉ HTTPS của hệ thống rồi thử lại.';if(showToast)toast(status.textContent);return Promise.resolve(null);}if(!navigator.geolocation){status.textContent='Thiết bị không hỗ trợ lấy vị trí.';if(showToast)toast(status.textContent);return Promise.resolve(null);}if(gpsRequest)return gpsRequest;status.textContent='Đang yêu cầu quyền truy cập vị trí…';gpsRequest=new Promise(resolve=>navigator.geolocation.getCurrentPosition(pos=>{gpsCoordinates={latitude:pos.coords.latitude,longitude:pos.coords.longitude,accuracy:pos.coords.accuracy};const loc=state.bootstrap.locations.find(l=>l.active);status.textContent=loc?`Đã cho phép · cách cơ sở ${Math.round(distance(gpsCoordinates.latitude,gpsCoordinates.longitude,loc.latitude,loc.longitude))} m · sai số ±${Math.round(gpsCoordinates.accuracy)} m`:`Đã cho phép · sai số ±${Math.round(gpsCoordinates.accuracy)} m`;resolve(gpsCoordinates);},error=>{gpsCoordinates=null;status.textContent=error.code===1?'Quyền vị trí đang bị chặn. Bật Vị trí trong quyền trang của trình duyệt rồi bấm “Yêu cầu lại / cập nhật vị trí”.':error.code===2?'Không xác định được vị trí. Bật dịch vụ định vị/GPS trên thiết bị rồi thử lại.':'Yêu cầu vị trí quá thời gian. Kiểm tra GPS rồi thử lại.';if(showToast)toast(status.textContent);resolve(null);},{enableHighAccuracy:true,timeout:20000,maximumAge:0})).finally(()=>{gpsRequest=null;});return gpsRequest;}
function distance(a,b,c,d){const rad=Math.PI/180;const h=Math.sin((c-a)*rad/2)**2+Math.cos(a*rad)*Math.cos(c*rad)*Math.sin((d-b)*rad/2)**2;return 6371000*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h));}
