document.addEventListener('click',event=>{const dialog=document.querySelector('#dialog');if(dialog?.open&&event.target===dialog)dialog.close();if(!event.target.closest('.filter-select'))document.querySelectorAll('.filter-select.open').forEach(wrap=>{wrap.classList.remove('open');wrap.querySelector('.filter-select-trigger')?.setAttribute('aria-expanded','false');});});

 window.addEventListener('hashchange',()=>{const role=state.bootstrap?.me.role;const page=location.hash.slice(1);const allowed={employee:['overview','checkin','attendance','schedule','requests','explanations'],manager:['overview','checkin','attendance','schedule','requests','explanations','approvals','explanation-approvals','supplement-approvals','employees','reports'],hr:['overview','checkin','attendance','schedule','requests','explanations','approvals','explanation-approvals','employees','departments','reports','shifts','locations','policy'],admin:['overview','schedule','approvals','explanation-approvals','supplement-approvals','employees','departments','reports','shifts','locations','policy','logs']}[role]||[];if(page&& !allowed.includes(page)){history.replaceState(null,'','#overview');render();toast('Bạn không có quyền truy cập mục này.');}});

window.addEventListener('hashchange',()=>{if(state.bootstrap)render();});
function render(){
 if(!state.bootstrap)return;
  const role=state.bootstrap.me.role;const page=location.hash.slice(1)||'overview';const allowed={employee:['overview','checkin','attendance','schedule','requests','explanations'],manager:['overview','checkin','attendance','schedule','requests','explanations','approvals','explanation-approvals','supplement-approvals','employees','reports'],hr:['overview','checkin','attendance','schedule','requests','explanations','approvals','explanation-approvals','employees','departments','reports','shifts','locations','policy'],admin:['overview','schedule','approvals','explanation-approvals','supplement-approvals','employees','departments','reports','shifts','locations','policy','logs']}[role]||[];
 if(!allowed.includes(page)){if(page!=='overview'){history.replaceState(null,'','#overview');toast('Bạn không có quyền truy cập mục này.');}return renderPage();}
 return renderPage();
}
function enhanceLeaveRequestForm(){
 const form=document.querySelector('#modal-form');
 const type=form?.querySelector('#request-type');
 if(!form||type?.value!=='leave'||form.dataset.leaveEnhanced)return;
 form.dataset.leaveEnhanced='true';
 const grid=form.querySelector('.form-grid');
 const addSelect=(name,title,items)=>{const wrap=document.createElement('label');wrap.className='field full';wrap.append(document.createTextNode(title+' '));const mark=document.createElement('em');mark.className='required-mark';mark.setAttribute('aria-hidden','true');mark.textContent='*';wrap.append(mark);const select=document.createElement('select');select.name=name;select.required=true;items.forEach(([value,label])=>{const option=document.createElement('option');option.value=value;option.textContent=label;select.append(option);});wrap.append(select);grid.insertBefore(wrap,grid.querySelector('[name="reason"]')?.closest('.field')||null);return{wrap,select};};
 const choices=leaveSessionRows().map(([value,name,startTime,endTime])=>[value,`${name} · ${startTime.slice(0,5)}–${endTime.slice(0,5)}`]);
 const start=addSelect('leaveSession','Ca nghỉ ngày đầu',choices);start.select.value='full';
 const end=addSelect('endLeaveSession','Ca nghỉ ngày cuối',choices);end.select.value='full';
 const info=document.createElement('p');info.className='field full leave-duration';grid.insertBefore(info,grid.querySelector('[name="reason"]')?.closest('.field')||null);
 const error=document.createElement('p');error.className='field full error-message';error.setAttribute('role','alert');grid.insertBefore(error,grid.querySelector('[name="reason"]')?.closest('.field')||null);
 const from=form.querySelector('[name="from"]'),to=form.querySelector('[name="to"]'),reason=form.querySelector('[name="reason"]'),handover=form.querySelector('[name="handoverEmployeeId"]'),handoverText=form.querySelector('[name="handover"]');
 const update=()=>{
  error.textContent='';const first=from.value,last=to.value;if(!first||!last){form.dataset.leaveOverlap='false';info.textContent='Chọn ngày bắt đầu và ngày kết thúc để xem thời lượng nghỉ.';return;}if(first.slice(0,7)!==last.slice(0,7)){error.textContent='Mỗi đơn nghỉ phép chỉ được chọn trong cùng một tháng.';form.dataset.leaveOverlap='true';info.textContent='';return;}
  const begin=new Date(first+'T12:00:00'),finish=new Date(last+'T12:00:00');const days=Math.round((finish-begin)/86400000)+1;
  if(days<1){error.textContent='Ngày kết thúc phải từ ngày bắt đầu trở đi.';info.textContent='';form.dataset.leaveOverlap='true';return;}
  const multi=days>1;end.wrap.hidden=!multi;end.wrap.style.display=multi?'grid':'none';
  const startMorning=start.select.querySelector('option[value="morning"]'),endAfternoon=end.select.querySelector('option[value="afternoon"]');startMorning.disabled=multi;endAfternoon.disabled=multi;
  if(multi&&start.select.value==='morning')start.select.value='afternoon';if(multi&&end.select.value==='afternoon')end.select.value='morning';
  if(!multi)end.select.value=start.select.value;
  const duration=multi?(days-2)+(start.select.value==='full'?1:0.5)+(end.select.value==='full'?1:0.5):(start.select.value==='full'?1:0.5);
  info.textContent='Tổng thời gian nghỉ: '+duration+' ngày công ('+days+' ngày lịch).';
  const dateValues=[];for(let d=new Date(begin);d<=finish;d.setDate(d.getDate()+1))dateValues.push(new Date(d));
  const month=first.slice(0,7);const booked=new Set();for(const r of state.requests){if(r.employeeId!==state.bootstrap.me.id||r.isCancellation||['cancelled','rejected'].includes(r.status)||!['leave','regular'].includes(r.type))continue;const a=new Date(r.from+'T12:00:00'),b=new Date(r.to+'T12:00:00');for(let d=new Date(a);d<=b;d.setDate(d.getDate()+1))if(d.toISOString().slice(0,7)===month)booked.add(d.toISOString().slice(0,10));}
  const overlap=dateValues.some(d=>booked.has(d.toISOString().slice(0,10)));form.dataset.leaveOverlap=String(overlap);if(overlap)error.textContent='Có ngày trùng với đơn nghỉ đã đăng ký. Kiểm tra Lịch làm việc hoặc Đơn của tôi.';
  const sundays=dateValues.some(d=>d.getDay()===0);const monthlyCount=booked.size+dateValues.length;const exceptional=sundays||monthlyCount>=5;reason.required=true;reason.minLength=exceptional?5:5;if(handover)handover.required=exceptional;if(handoverText)handoverText.required=exceptional&&state.bootstrap.policy.weekendRestricted&&dateValues.some(d=>d.getDay()===0||d.getDay()===6);[[reason,true],[handover,exceptional],[handoverText,handoverText?.required]].forEach(([control,required])=>{const label=control?.closest('.field');if(!label)return;let mark=label.querySelector('.required-mark');if(required&&!mark){mark=document.createElement('em');mark.className='required-mark';mark.setAttribute('aria-hidden','true');mark.textContent='*';control.before(mark);}else if(!required&&mark)mark.remove();});
  if(exceptional&&!overlap)error.textContent=sundays?'Nghỉ Chủ nhật cần giải trình và người bàn giao.':monthlyCount>=5?'Tổng nghỉ tháng đạt từ 5 ngày, cần giải trình và người bàn giao.':'';
 };
 form.addEventListener('submit',event=>{if(form.dataset.leaveOverlap==='true'){event.preventDefault();event.stopImmediatePropagation();const message=form.querySelector('#form-error');if(message)message.textContent='Không thể gửi đơn do có ngày đã đăng ký nghỉ.';}},true);[from,to,start.select,end.select].forEach(control=>control.addEventListener('change',update));update();
}
const leaveRequestObserver=new MutationObserver(()=>{const root=document.querySelector('#dialog-content')||document;enhanceLeaveRequestForm();enhanceDatePickers(root);enhanceTimePickers(root);});
const dialogContent=document.querySelector('#dialog-content');if(dialogContent)leaveRequestObserver.observe(dialogContent,{childList:true,subtree:true});

document.addEventListener('click',event=>{const path=event.composedPath(),inside=selector=>path.some(node=>node instanceof Element&&node.matches(selector));if(!inside('.date-picker'))document.querySelectorAll('.date-picker.open').forEach(wrap=>{wrap.classList.remove('open');wrap.querySelector('.date-picker-popup').hidden=true;wrap.querySelector('.date-picker-trigger').setAttribute('aria-expanded','false');});if(!inside('.time-picker'))document.querySelectorAll('.time-picker.open').forEach(wrap=>{wrap.classList.remove('open');wrap.querySelector('.time-picker-popup').hidden=true;wrap.querySelector('.time-picker-trigger').setAttribute('aria-expanded','false');});});
